-- Split oversized BlackArch categories into smaller pages.
local function paginate_menu(items, items_per_page)
    if type(items) ~= "table" or #items <= items_per_page then
        return items
    end

    local pages = {}
    local total_pages = math.ceil(#items / items_per_page)

    for page_number = 1, total_pages do
        local page_items = {}
        local first_item = ((page_number - 1) * items_per_page) + 1
        local last_item = math.min(
            page_number * items_per_page,
            #items
        )

        for item_number = first_item, last_item do
            page_items[#page_items + 1] = items[item_number]
        end

        pages[#pages + 1] = {
            string.format(
                "Page %d of %d",
                page_number,
                total_pages
            ),
            page_items
        }
    end

    return pages
end

-- Apply pagination to every BlackArch tool category.
for _, category in ipairs(blackarchmenu) do
    category[2] = paginate_menu(category[2], 22)
end
return blackarchmenu
